  `temperature` double NOT NULL,
  `humidity` double NOT NULL,
  `vibration` double NOT NULL,
  `pressure` double NOT NULL,
  `machine_state` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `timestamp` datetime(3) NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `telemetry_event_id_key` (`event_id`),
  KEY `telemetry_device_id_idx` (`device_id`),
  CONSTRAINT `telemetry_device_id_fkey` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
